import type { StoredPage } from "./types";

// Page classification for prioritising SEO work. Evidence only: URL patterns
// common to website builders (WordPress archives, sample content), the page's
// own robots instructions and its status. When nothing points to a special
// kind the page is an ordinary page; we never guess "unimportant".
//
// Kinds:
//   home     the start page
//   page     an ordinary content page (counts fully in the content checks)
//   archive  listings generated by the CMS: author, category, tag, date,
//            pagination, search, feeds (useful for navigation, rarely a target
//            for search on their own)
//   sample   default or test content of a website builder ("Hello world!",
//            "Sample Page", "Voorbeeldpagina")
//   legal    privacy, cookies, terms, disclaimer (fine to have, not a search target)
//   utility  login, account, cart, checkout (not meant for search)
//   error    not a 2xx HTML page
// `intentionalNoindex`: a noindex on an archive/legal/utility/sample page is
// treated as a deliberate choice, not a problem.

export type PageKind = "home" | "page" | "archive" | "sample" | "legal" | "utility" | "error";

export const KIND_LABEL: Record<PageKind, string> = {
  home: "Homepage",
  page: "Pagina",
  archive: "Archief",
  sample: "Voorbeeldpagina",
  legal: "Juridisch",
  utility: "Account/winkelwagen",
  error: "Foutpagina",
};

const ARCHIVE = [/\/(author|auteur)\/[^/]+/i, /\/(category|categorie|tag|tags|label)\/[^/]+/i, /\/page\/\d+\/?$/i, /\/\d{4}\/(\d{2}\/)?(\d{2}\/)?$/, /\/(feed|rss|search|zoeken)(\/|$)/i, /[?&](s|p|page|paged|cat|tag)=/i];
const SAMPLE_PATH = [/\/hello-world\/?$/i, /\/hallo-wereld\/?$/i, /\/sample-page\/?$/i, /\/voorbeeld-?pagina\/?$/i, /\/(test|testpagina|test-page)\/?$/i];
const SAMPLE_TITLE = [/^hello world!?(\s|$|[|–-])/i, /^hallo wereld!?(\s|$|[|–-])/i, /^sample page(\s|$|[|–-])/i, /^voorbeeldpagina(\s|$|[|–-])/i];
const LEGAL = [/\/(privacy|privacybeleid|privacyverklaring|privacy-policy|cookies?|cookiebeleid|cookie-policy|algemene-voorwaarden|voorwaarden|terms|disclaimer|imprint|colofon)(\/|$)/i];
const UTILITY = [/\/(wp-login|login|inloggen|my-account|mijn-account|account|cart|winkelwagen|winkelmand|checkout|afrekenen|wp-admin)(\/|$)/i];

const isOk = (p: StoredPage) => p.status >= 200 && p.status < 300 && /html/i.test(p.contentType || "text/html");

export function classifyPage(p: StoredPage, homeUrl?: string): PageKind {
  if (!isOk(p)) return "error";
  let path = "/";
  try {
    const u = new URL(p.url);
    path = u.pathname + u.search;
    if (homeUrl && new URL(homeUrl).host === u.host && (u.pathname === "/" || u.pathname === "") && !u.search) return "home";
  } catch {
    // keep defaults
  }
  if (path === "/" || path === "") return "home";
  if (SAMPLE_PATH.some((r) => r.test(path)) || SAMPLE_TITLE.some((r) => r.test(p.title.trim()))) return "sample";
  if (ARCHIVE.some((r) => r.test(path))) return "archive";
  if (LEGAL.some((r) => r.test(path))) return "legal";
  if (UTILITY.some((r) => r.test(path))) return "utility";
  return "page";
}

/** Pages that carry the business in search: home and ordinary pages that may be indexed. */
export function isPrimary(p: StoredPage, homeUrl?: string) {
  const k = classifyPage(p, homeUrl);
  return (k === "home" || k === "page") && !p.noindex;
}

/** A noindex that looks deliberate (archives, legal, account pages, sample content). */
export function intentionalNoindex(p: StoredPage, homeUrl?: string) {
  if (!p.noindex) return false;
  const k = classifyPage(p, homeUrl);
  return k === "archive" || k === "legal" || k === "utility" || k === "sample";
}
